Your expense tracker is below: add an item with an amount and category, and the total, budget left and category split update as you go. I can't promise it saves after you close the chat, so note down anything you want to keep.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:14px;background:#faf9f6;color:#222}
h2{margin:0 0 10px;font-size:18px}
.row{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{padding:7px;border:1px solid #ccc;border-radius:6px;font-size:14px}
input{flex:1;min-width:90px}
button{background:#2f7d5b;color:#fff;border:0;cursor:pointer}
.card{background:#fff;border:1px solid #e5e2da;border-radius:10px;padding:10px;margin-bottom:10px}
.big{font-size:22px;font-weight:600}
.cap{font-size:12px;color:#777}
.bar{height:8px;background:#2f7d5b;border-radius:4px}
.item{display:flex;justify-content:space-between;align-items:center;padding:5px 0;border-bottom:1px solid #eee;font-size:14px}
.item button{background:#c0392b;padding:2px 8px;margin-left:8px}
.over{color:#c0392b}
</style></head><body>
<h2>Monthly expenses</h2>
<div class="card">
<div class="row">
<input id="b" type="number" placeholder="Monthly budget (₹)">
</div>
<div class="cap">Spent</div><div class="big" id="t">₹0</div>
<div class="cap" id="left">Set a budget to see what is left</div>
</div>
<div class="card">
<div class="row">
<input id="n" placeholder="What for?">
<input id="a" type="number" placeholder="Amount (₹)">
</div>
<div class="row">
<select id="c"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option></select>
<input id="d" type="date">
<button id="add">Add</button>
</div>
</div>
<div class="card"><div class="cap">By category</div><div id="cats"></div></div>
<div class="card"><div class="cap">All items</div><div id="list"></div></div>
<script>
var items=[],$=function(i){return document.getElementById(i)};
var fmt=function(x){return '₹'+Number(x).toLocaleString('en-IN')};
$('d').value=new Date().toISOString().slice(0,10);
try{items=JSON.parse(localStorage.getItem('exp')||'[]')}catch(e){}
function save(){try{localStorage.setItem('exp',JSON.stringify(items))}catch(e){}}
function esc(s){return s.replace(/[&<>]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;'}[c]})}
function draw(){
var tot=0,by={};
items.forEach(function(i){tot+=i.a;by[i.c]=(by[i.c]||0)+i.a});
$('t').textContent=fmt(tot);
var b=Number($('b').value);
if(b>0){var l=b-tot;$('left').innerHTML=l>=0?fmt(l)+' left of '+fmt(b):'<span class="over">Over budget by '+fmt(-l)+'</span>'}
else $('left').textContent='Set a budget to see what is left';
var h='';
Object.keys(by).sort(function(x,y){return by[y]-by[x]}).forEach(function(k){
h+='<div class="item"><span>'+k+'</span><span>'+fmt(by[k])+' ('+Math.round(by[k]/tot*100)+'%)</span></div><div class="bar" style="width:'+(by[k]/tot*100)+'%"></div>'});
$('cats').innerHTML=h||'<div class="cap">Nothing yet</div>';
var s=items.map(function(i,x){return{i:i,x:x}}).sort(function(p,q){return q.i.d<p.i.d?-1:1});
$('list').innerHTML=s.map(function(o){return '<div class="item"><span>'+esc(o.i.n)+' <span class="cap">'+o.i.c+' · '+o.i.d+'</span></span><span>'+fmt(o.i.a)+'<button data-x="'+o.x+'">x</button></span></div>'}).join('')||'<div class="cap">Nothing yet</div>';
}
$('add').onclick=function(){
var a=Number($('a').value),n=$('n').value.trim();
if(!(a>0)||!n)return;
items.push({n:n,a:a,c:$('c').value,d:$('d').value});
$('n').value='';$('a').value='';save();draw();
};
$('list').onclick=function(e){var x=e.target.getAttribute('data-x');if(x!==null){items.splice(Number(x),1);save();draw()}};
$('b').oninput=draw;
draw();
</script>
</body></html>
```

Here's a water tracker with a goal of 8 glasses. Tap + after each glass, and it saves per day if your viewer allows it.

```page
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Water tracker</title>
<style>
  body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; display: flex; justify-content: center; background: #f2f8fb; color: #12303d; }
  .card { background: #fff; border-radius: 16px; padding: 24px; width: 100%; max-width: 340px; text-align: center; box-shadow: 0 2px 10px rgba(0,0,0,.08); }
  h1 { font-size: 20px; margin: 0 0 4px; }
  .date { font-size: 13px; opacity: .7; margin-bottom: 16px; }
  .count { font-size: 48px; font-weight: 700; margin: 8px 0; }
  .bar { height: 12px; background: #dbeaf1; border-radius: 6px; overflow: hidden; margin: 12px 0 16px; }
  .fill { height: 100%; width: 0; background: #2a9df4; transition: width .3s; }
  .glasses { font-size: 26px; letter-spacing: 4px; min-height: 36px; margin-bottom: 16px; }
  button { font-size: 20px; border: 0; border-radius: 10px; padding: 10px 22px; margin: 0 4px; cursor: pointer; background: #2a9df4; color: #fff; }
  button.alt { background: #dbeaf1; color: #12303d; }
  .reset { font-size: 13px; padding: 6px 14px; margin-top: 16px; }
  .msg { margin-top: 12px; min-height: 20px; font-size: 14px; }
</style>
</head>
<body>
<div class="card">
  <h1>Water today</h1>
  <div class="date" id="date"></div>
  <div class="count"><span id="n">0</span> / 8</div>
  <div class="bar"><div class="fill" id="fill"></div></div>
  <div class="glasses" id="glasses"></div>
  <button class="alt" id="minus" aria-label="Remove a glass">&minus;</button>
  <button id="plus" aria-label="Add a glass">+</button>
  <div class="msg" id="msg"></div>
  <button class="alt reset" id="reset">Reset today</button>
</div>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var key = "water-" + today;
  var count = 0;
  try { count = parseInt(localStorage.getItem(key), 10) || 0; } catch (e) {}

  function save() { try { localStorage.setItem(key, String(count)); } catch (e) {} }

  function render() {
    document.getElementById("date").textContent = new Date().toDateString();
    document.getElementById("n").textContent = count;
    document.getElementById("fill").style.width = Math.min(100, count / GOAL * 100) + "%";
    var g = "";
    for (var i = 0; i < GOAL; i++) g += i < count ? "\uD83D\uDCA7" : "\u25EF";
    document.getElementById("glasses").textContent = g;
    var msg = count >= GOAL ? "Goal reached. Well done!" : (GOAL - count) + " more to go";
    document.getElementById("msg").textContent = msg;
  }

  document.getElementById("plus").onclick = function () { count++; save(); render(); };
  document.getElementById("minus").onclick = function () { if (count > 0) { count--; save(); render(); } };
  document.getElementById("reset").onclick = function () { count = 0; save(); render(); };
  render();
</script>
</body>
</html>
```
